WITH cleaned AS (SELECT *, DATE_FORMAT(paid_at, 'MMM yyyy') AS paid_at_label, COALESCE(amount, 0) AS amount_filled FROM payments WHERE paid_at > TIMESTAMP '2023-09-07 02:00:00' AND method IS DISTINCT FROM 'card'), with_dims AS (SELECT a.id, a.order_id, a.paid_at, a.status, a.paid_at_label, a.amount_filled, d.channel, d.order_date, d.amount AS order_amount FROM cleaned a LEFT JOIN orders d ON a.order_id = d.id WHERE d.order_date BETWEEN '2024-02-01' AND '2024-12-01'), cleaned_payments AS (SELECT *, TO_DATE(paid_at) AS paid_at_date FROM with_dims WHERE paid_at > TO_DATE('2023-08-30') AND channel IS NOT NULL), with_windows AS (SELECT *, SUM(amount_filled) OVER (ORDER BY CAST(paid_at AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_filled_sum_7d, SUM(amount_filled) OVER (PARTITION BY channel ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount_filled FROM cleaned_payments) SELECT o.status AS order_status, o.channel AS order_channel, COUNT(*) AS cnt, MIN(e.cumulative_amount_filled) AS min_cumulative_amount_filled, GROUPING_ID() AS gid FROM with_windows e LEFT JOIN orders o ON e.order_id = o.id GROUP BY GROUPING SETS ((o.status, o.channel), (o.status), ());
